        __shared__ float sh_sumsq[256];
        sh_sum[threadIdx.x] = local_sum;
        sh_sumsq[threadIdx.x] = local_sumsq;
        __syncthreads();

        for (int s = blockDim.x / 2; s > 32; s >>= 1) {
            if (threadIdx.x < s) {
                sh_sum[threadIdx.x] += sh_sum[threadIdx.x + s];
                sh_sumsq[threadIdx.x] += sh_sumsq[threadIdx.x + s];
            }
            __syncthreads();
